// CSD_RATIONALE_BEGIN
// Root-cause analysis from attempt 1:
//   - 5 examples: unterminated spans — the model opened "<<" but the parser
//     admitted a single repeating token ("!") as a valid identifier prefix, so
//     the span never reached a completable state and the step budget ran out.
//   - 7 examples: malformed/empty constrained content — same root cause.
//   - 28 examples: syntactically valid but semantically wrong — reasoning
//     errors, missing int() wrappers, wrong variable references.
//
// Fix strategy:
//   1. AppendTaskGuidance with explicit instructions for int(), variable usage,
//      and the required output format.
//   2. Outside a span: generate one UnconstrainedStep at a time; use
//      RenderedEndsWith(generated, "<<") — not token equality — to detect entry.
//   3. Inside a span: immediately delegate the entire span lifecycle to
//      CloseSpanWithinBudget with a per-span cap of spanBudget=50. This helper
//      is dead-end-aware and tracks the longest prefix that is parser-complete,
//      guaranteeing that ">>" is emitted at that checkpoint rather than looping
//      on an uncompletable token sequence until the global budget runs out.
//   4. After closing, return to free generation for the next reasoning segment
//      and the next << >> span.
//
// Budget: 900 total steps. Typical problem: ~33 free tokens before first "<<",
// ~4-5 spans × 50-step budget = ~250 constrained steps, ~600+ remaining for
// inter-span reasoning. Well within budget.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch (UnconstrainedStep):
//     next == eosToken: we break without changing span state; invariant holds.
//     next != eosToken, !RenderedEndsWith: insideConstrainedOut stays false,
//       implication vacuously true.
//     next != eosToken, RenderedEndsWith "<<": we set insideConstrainedOut := true
//       and currentConstrainedOut := []. IsValidPrefix([]) holds by the method
//       precondition (parser.IsValidPrefix([])), so the invariant is preserved.
//
//   Inside-span branch (CloseSpanWithinBudget):
//     The helper's postcondition asserts insideOut ==> parser.IsValidPrefix(currentOut)
//     in both the "span closed" (insideOut = false, implication vacuous) and
//     "span still open" (IsValidPrefix holds for the advanced currentOut) sub-cases.
//     Invariant is therefore preserved unconditionally.
//
// Invariant 2 – progress: |generated| <= |generatedPrefix| + steps
//
//   Outside-span branch: steps += 1; generated grows by at most one token (only
//     when next != eosToken). |generated| increases by ≤ 1 while steps increases
//     by exactly 1. Bound preserved.
//
//   Inside-span branch: budget = min(maxSteps - steps, spanBudget) ≤ maxSteps - steps,
//     so steps_new = steps + budget ≤ maxSteps (invariant 0 <= steps <= maxSteps
//     is maintained). CloseSpanWithinBudget postcondition gives |cg| ≤ |generated|
//     + budget, hence |cg| ≤ |generatedPrefix| + steps + budget
//     = |generatedPrefix| + steps_new. Bound preserved.
//     Visible growth may be strictly less than budget (e.g., if only 8 of 50
//     budget steps produce tokens); the conservative accounting does not
//     violate the bound.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve this math problem step by step. " +
  "Wrap every intermediate computed sub-expression and the final answer in << >>. " +
  "Inside << >>, write a complete, self-contained arithmetic expression using only: " +
  "numbers, the exact variable names from the problem, and the operators +, -, *, /, //, %, (), int(). " +
  "Use int() when the quantity is a whole number, e.g., <<int(n * frac_1 * frac_2)>>. " +
  "Use // for integer division between integer quantities. " +
  "Do not include natural-language text inside << >>. " +
  "Always finish with: The final answer is <<expression>>.");

var steps: nat := 0;
var spanBudget: nat := 50;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    var remaining := maxSteps - steps;
    var budget := if remaining <= spanBudget then remaining else spanBudget;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + budget;
  }
}

cost := steps;

